import React from 'react';

import { formatAltitude } from '@helpers/formatHelper';

import { IObstacle } from '../../@types/obstacles.types';
import ObstacleCategoryBadge from '../ObstacleCategoryBadge/ObstacleCategoryBadge';
import { ObstacleIcon } from '../ObstacleIcon/ObstacleIcon';
interface IObstacleListItemProps {
  obstacle: IObstacle;
}

const ObstacleListItem: React.FC<IObstacleListItemProps> = ({ obstacle }) => {
  return (
    <div className="d-flex align-items-center">
      <ObstacleIcon type={obstacle.type} />
      &nbsp;&nbsp;
      <strong>{obstacle.name}</strong>
      &nbsp;
      <ObstacleCategoryBadge category={obstacle.category} />
      &nbsp;
      {formatAltitude(obstacle.altitude)}
      {obstacle.comment.length > 0 && (
        <em className="d-block text-muted">
          <small>{obstacle.comment}</small>
        </em>
      )}
    </div>
  );
};

export default ObstacleListItem;
